    #[test]
    fn risk_scout_prefers_finding_id_and_retains_semantic_key_compatibility() {
        let finding = |identifier_field: &str, identifier: &str| {
            let mut finding = json!({
                "lens": "correctness-behavior",
                "severity": "MINOR",
                "security_impact": "none",
                "safety_impact": "none",
                "likelihood": "possible",
                "causality": "caused",
                "path": "src/lib.rs",
                "message": "A bounded changed-path defect.",
                "relevance": {
                    "category": "diff_changed_file",
                    "explanation": "The defect is in the changed file."
                }
            });
            finding[identifier_field] = json!(identifier);
            finding
        };

        for (field, identifier) in [
            ("finding_id", "preferred-finding-id"),
            ("semantic_key", "legacy-semantic-key"),
        ] {
            let planned: Value = serde_json::from_str(
                &plan_result(&assessed_plan_arguments(
                    &format!("finding-id-{field}"),
                    "medium",
                    &[("correctness-behavior", "medium")],
                    json!([finding(field, identifier)]),
                ))
                .expect("preferred and compatibility identifiers are accepted"),
            )
            .expect("plan json");
            assert_eq!(
                planned["state"]["risk_plan"]["findings"][0]["id"],
                identifier
            );
            assert_eq!(
                planned["state"]["risk_plan"]["findings"][0]["finding_id"],
                identifier
            );
        }

        let mut mismatched = finding("finding_id", "preferred");
        mismatched["semantic_key"] = json!("different");
        let error = plan_result(&assessed_plan_arguments(
            "finding-id-alias-mismatch",
            "medium",
            &[("correctness-behavior", "medium")],
            json!([mismatched]),
        ))
        .expect_err("mismatched aliases must fail closed");
        assert_eq!(error, "risk_assessment_finding_id_alias_mismatch=true");
    }

    #[test]
    fn json_rpc_initialize_negotiates_supported_protocol_versions() {
        let supported = handle_json_rpc(&json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "test", "version": "1"}
            }
        }))
        .expect("supported initialize response");
        assert_eq!(supported["result"]["protocolVersion"], "2024-11-05");
        assert!(supported["result"]["instructions"]
            .as_str()
            .unwrap()
            .contains("final_review.assess_risk before final_review.plan"));

        let editor = ReviewCoordinator::with_service_surface(ServiceSurface::WorkspaceEditor)
            .handle_json_rpc(&json!({
                "jsonrpc": "2.0",
                "id": 2,
                "method": "initialize",
                "params": {
                    "protocolVersion": "2024-11-05",
                    "capabilities": {},
                    "clientInfo": {"name": "test", "version": "1"}
                }
            }))
            .expect("editor initialize response");
        let instructions = editor["result"]["instructions"]
            .as_str()
            .expect("editor instructions");
        assert!(instructions.contains("hash-checked file mutations"));
        assert!(!instructions.contains("final_review"));

        let unsupported = handle_json_rpc(&json!({
            "jsonrpc": "2.0",
            "id": 2,
            "method": "initialize",
            "params": {
                "protocolVersion": "1900-01-01",
                "capabilities": {},
                "clientInfo": {"name": "test", "version": "1"}
            }
        }))
        .expect("unsupported initialize response");
        assert_eq!(unsupported["error"]["code"], -32602);
        assert_eq!(unsupported["error"]["data"]["requested"], "1900-01-01");
        assert!(unsupported["error"]["data"]["supported"]
            .as_array()
            .unwrap()
            .contains(&json!("2024-11-05")));
    }

    #[test]
    fn json_rpc_plan_rejects_malformed_review_context() {
        let mut coordinator = ReviewCoordinator::default();
        let cases = [
            (
                "scope",
                json!("not-a-supported-scope"),
                "scope_invalid expected=base|uncommitted",
            ),
            (
                "scope",
                json!(42),
                "scope_invalid expected=base|uncommitted",
            ),
            ("base", json!(""), "base_invalid expected=nonempty-string"),
            (
                "base",
                json!(" \t\n"),
                "base_invalid expected=nonempty-string",
            ),
            ("base", json!(42), "base_invalid expected=nonempty-string"),
            (
                "user_request",
                json!(42),
                "user_request_must_be_string=true",
            ),
            (
                "acceptance_criteria",
                json!("one criterion"),
                "acceptance_criteria_must_be_array=true",
            ),
            (
                "explicit_concerns",
                json!(["valid", 42]),
                "explicit_concerns_item_must_be_string index=1",
            ),
        ];

        for (index, (field, malformed, expected_error)) in cases.into_iter().enumerate() {
            let mut arguments = add_test_risk_assessment(
                json!({
                    "session_id": format!("malformed-context-{index}"),
                    "changed_files": ["src/new.rs"],
                    "diff_hash": "same"
                }),
                "high",
                &[("correctness-behavior", "high")],
                json!([]),
            );
            arguments[field] = malformed;
            let response = coordinator
                .handle_json_rpc(&json!({
                    "jsonrpc": "2.0",
                    "id": index,
                    "method": "tools/call",
                    "params": {
                        "name": "final_review.plan",
                        "arguments": arguments
                    }
                }))
                .expect("malformed plan response");

            assert_eq!(response["error"]["code"], -32602);
            assert_eq!(response["error"]["message"], expected_error);
        }
    }

    #[test]
    fn json_rpc_tools_call_drives_final_review_state_machine() {
        let mut coordinator = ReviewCoordinator::default();
        let plan_arguments = add_test_risk_assessment(
            json!({
                "session_id": "rpc-review",
                "base": "HEAD",
                "scope": "uncommitted",
                "changed_files": ["src/new.rs"],
                "diff_hash": "same",
                "pre_filter_model_role": "explicit-pre"
            }),
            "high",
            &[("correctness-behavior", "high")],
            json!([]),
        );
        let plan_response = coordinator
            .handle_json_rpc(&json!({
                "jsonrpc": "2.0",
                "id": 1,
                "method": "tools/call",
                "params": {
                    "name": "final_review.plan",
                    "arguments": plan_arguments
                }
            }))
            .expect("plan response");
        let plan_text = plan_response["result"]["content"][0]["text"]
            .as_str()
            .expect("plan text");
        let plan: Value = serde_json::from_str(plan_text).expect("plan json");
        assert_eq!(plan["model_roles"]["pre_filter"], "explicit-pre");
        assert_eq!(plan["assignments"][0]["close_after_result"], true);
        assert_eq!(
            plan["assignments"][0]["subagent_key"],
            "rpc-review:1:correctness-behavior"
        );

        let mut state = plan["state"].clone();
        let required = state["required_clean_iterations"]
            .as_u64()
            .expect("required passes");
        for expected_clean_streak in 1..=required {
            let lens_results = clean_lens_results_for(&state);
            let advance_response = coordinator
                .handle_json_rpc(&json!({
                    "jsonrpc": "2.0",
                    "id": expected_clean_streak,
                    "method": "tools/call",
                    "params": {
                        "name": "final_review.advance",
                        "arguments": {
                            "state": state.clone(),
                            "lens_results": lens_results,
                            "current_diff_hash": "same"
                        }
                    }
                }))
                .expect("advance response");
            let advance_text = advance_response["result"]["content"][0]["text"]
                .as_str()
                .expect("advance text");
            let advanced: Value = serde_json::from_str(advance_text).expect("advance json");
            assert_eq!(advanced["state"]["clean_streak"], expected_clean_streak);
            assert_eq!(
                advanced["filtered"]["transition"]["complete_lens_set"],
                true
            );
            state = advanced["state"].clone();
        }
        assert!(review_state_complete(&state));
        let database = PathBuf::from(
            state["out_of_scope_report_artifact"]
                .as_str()
                .expect("review event database"),
        );
        let connection = open_review_connection(&database).expect("review event store");
        let encoded: Vec<String> = connection
            .prepare("SELECT event_data FROM eventcore_events ORDER BY rowid")
            .expect("event query")
            .query_map([], |row| row.get(0))
            .expect("event rows")
            .collect::<Result<_, _>>()
            .expect("event payloads");
        assert!(encoded
            .iter()
            .all(|event| !event.contains("\"resulting_state\":")));
        assert!(encoded.iter().any(|event| event.contains("\"changes\":")));
    }

    #[test]
    fn json_rpc_verifier_resolution_uses_persisted_semantic_continuation() {
        let mut coordinator = ReviewCoordinator::default();
        let plan_arguments = add_test_risk_assessment(
            json!({
                "session_id": "pending-verifier-review",
                "changed_files": ["src/new.rs"],
                "diff_hash": "same"
            }),
            "high",
            &[("correctness-behavior", "high")],
            json!([]),
        );
        let plan_response = coordinator
            .handle_json_rpc(&json!({
                "jsonrpc": "2.0",
                "id": 1,
                "method": "tools/call",
                "params": {
                    "name": "final_review.plan",
                    "arguments": plan_arguments
                }
            }))
            .expect("plan response");
        let plan: Value = serde_json::from_str(
            plan_response["result"]["content"][0]["text"]
                .as_str()
                .expect("plan text"),
        )
        .expect("plan json");
        let state = plan["state"].clone();
        let mut finding_results = clean_lens_results_for(&state);
        finding_results[0]["status"] = json!("findings");
        finding_results[0]["findings"] = json!([{
            "id": "finding-1",
            "severity": "CRITICAL",
            "causality": "caused",
            "causality_evidence": "The changed branch introduces the authorization failure.",
            "likelihood": "possible",
            "security_impact": "critical",
            "safety_impact": "none",
            "path": "src/new.rs",
            "message": "real issue",
            "relevance": {
                "category": "diff_changed_file",
                "explanation": "changed file"
            }
        }]);

        let pending_response = coordinator
            .handle_json_rpc(&json!({
                "jsonrpc": "2.0",
                "id": 2,
                "method": "tools/call",
                "params": {
                    "name": "final_review.advance",
                    "arguments": {
                        "state": state.clone(),
                        "lens_results": finding_results.clone(),
                        "current_diff_hash": "same"
                    }
                }
            }))
            .expect("pending response");
        let pending: Value = serde_json::from_str(
            pending_response["result"]["content"][0]["text"]
                .as_str()
                .expect("pending text"),
        )
        .expect("pending json");
        assert_eq!(pending["transition_status"], "verifier_required");
        let assignment = &pending["verifier_assignment"];
        let database = PathBuf::from(
            state["out_of_scope_report_artifact"]
                .as_str()
                .expect("review event database"),
        );
        let connection = open_review_connection(&database).expect("review event store");
        let requested: String = connection
            .query_row(
                "SELECT event_data FROM eventcore_events WHERE event_data LIKE '%VerifierRequested%' ORDER BY rowid DESC LIMIT 1",
                [],
                |row| row.get(0),
            )
            .expect("verifier request event");
        assert!(requested.contains("\"verifier_continuation\":"));
        assert!(!requested.contains("\"arguments\":"));
        let mut coordinator = ReviewCoordinator::default();

        let bypass_response = coordinator
            .handle_json_rpc(&json!({
                "jsonrpc": "2.0",
                "id": 3,
                "method": "tools/call",
                "params": {
                    "name": "final_review.advance",
                    "arguments": {
                        "state": state.clone(),
                        "lens_results": clean_lens_results_for(&state),
                        "current_diff_hash": "same"
                    }
                }
            }))
            .expect("bypass response");
        assert_eq!(
            bypass_response["error"]["message"],
            "pending_verifier_result_required=true"
        );

        let verifier_result = json!({
            "subagent_key": assignment["subagent_key"],
            "assignment_id": assignment["assignment_id"],
            "model_role": assignment["model_role"],
            "status": "failed",
            "rationale": "Verifier unavailable; retain every finding.",
            "caller_attestation": {
                "model_role": assignment["model_role"],
                "fresh_context": true,
                "closed_after_result": true
            }
        });
        let advanced_response = coordinator
            .handle_json_rpc(&json!({
                "jsonrpc": "2.0",
                "id": 4,
                "method": "tools/call",
                "params": {
                    "name": "final_review.advance",
                    "arguments": {
                        "state": state,
                        // The verifier command consumes the typed filtered
                        // facts captured by VerifierRequested. A replayed lens
                        // payload is compatibility input, not authority.
                        "lens_results": clean_lens_results_for(&plan["state"]),
                        "current_diff_hash": "same",
                        "verifier_result": verifier_result
                    }
                }
            }))
            .expect("verified advance response");
        let advanced: Value = serde_json::from_str(
            advanced_response["result"]["content"][0]["text"]
                .as_str()
                .unwrap_or_else(|| panic!("advanced text: {advanced_response}")),
        )
        .expect("advanced json");
        assert_eq!(advanced["transition_status"], "advanced");
        assert_eq!(advanced["verification"]["status"], "failed_retained");
        let mut restarted = ReviewCoordinator::default();
        let resumed_response = restarted
            .handle_json_rpc(&json!({
                "jsonrpc": "2.0",
                "id": 5,
                "method": "tools/call",
                "params": {
                    "name": "final_review.resume_latest",
                    "arguments": {
                        "session_id": advanced["state_ref"]["session_id"],
                        "project_root": advanced["state_ref"]["project_root"],
                        "work_item_id": advanced["state_ref"].get("work_item_id").cloned().unwrap_or(Value::Null)
                    }
                }
            }))
            .expect("resume committed verifier projection");
        let resumed: Value = serde_json::from_str(
            resumed_response["result"]["content"][0]["text"]
                .as_str()
                .expect("resume text"),
        )
        .expect("resume json");
        assert_eq!(resumed["state_ref"], advanced["state_ref"]);
    }

